    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imported |= {(a.asname or a.name.split('.')[0]) for a in node.names}
        elif isinstance(node, ast.ImportFrom):
            imported |= {(a.asname or a.name) for a in node.names}
    used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | \
           {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)} | \
           {getattr(n.value,'id',None) for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    text_names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute):
            cur = node
            while isinstance(cur, ast.Attribute):
                cur = cur.value
            if isinstance(cur, ast.Name):
                text_names.add(cur.id)
    unused = sorted(i for i in imported if i not in used and i not in text_names)
    print(name, 'unused imports:', unused)
